import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;

import androidx.test.ext.junit.runners.AndroidJUnit4;

import org.junit.Test;
import org.junit.runner.RunWith;

import java.security.KeyStore;
import java.util.UUID;

import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

@RunWith(AndroidJUnit4.class)
public class EncryptedKeyTest {
    private static final String CURRENT_KEY_ID_PREFIX = "encryptedKeyTestCurrent-";

    @Test
    public void currentRecordRoundTripsAfterAndroidKeyStoreKeyReload() throws Exception {
        String keyId = CURRENT_KEY_ID_PREFIX + UUID.randomUUID();
        KeyStore keyStore = KeyStore.getInstance("AndroidKeyStore");
        keyStore.load(null);

        try {
            SecretKey currentKey = generateCurrentKey(keyId);
            SecretKey plaintext = generateSoftwareAesKey();

            EncryptedKey encrypted = EncryptedKey.encrypt(currentKey, plaintext, keyId);

            assertTrue(encrypted.isCurrentRecord());
            assertEquals(keyId, encrypted.getWrappingKeyId());

            SecretKey reloadedCurrentKey = (SecretKey) keyStore.getKey(keyId, null);
            assertNotNull(reloadedCurrentKey);

            SecretKey decrypted = encrypted.decrypt(generateSoftwareAesKey(), reloadedCurrentKey);
            assertSecretKeyEquals(plaintext, decrypted);
        } finally {
            if (keyStore.containsAlias(keyId)) {
                keyStore.deleteEntry(keyId);
            }
        }
    }

    @Test
    public void repeatedCurrentRecordsDecryptWithTheSameReloadedAndroidKeyStoreKey() throws Exception {
        String keyId = CURRENT_KEY_ID_PREFIX + UUID.randomUUID();
        KeyStore keyStore = KeyStore.getInstance("AndroidKeyStore");
        keyStore.load(null);

        try {
            SecretKey currentKey = generateCurrentKey(keyId);
            SecretKey firstPlaintext = generateSoftwareAesKey();
            SecretKey secondPlaintext = generateSoftwareAesKey();

            EncryptedKey firstRecord = EncryptedKey.encrypt(currentKey, firstPlaintext, keyId);
            EncryptedKey secondRecord = EncryptedKey.encrypt(currentKey, secondPlaintext, keyId);

            SecretKey reloadedCurrentKey = (SecretKey) keyStore.getKey(keyId, null);
            assertNotNull(reloadedCurrentKey);
            assertSecretKeyEquals(
                    firstPlaintext,
                    firstRecord.decrypt(generateSoftwareAesKey(), reloadedCurrentKey));
            assertSecretKeyEquals(
                    secondPlaintext,
                    secondRecord.decrypt(generateSoftwareAesKey(), reloadedCurrentKey));
